92	    fn may_have_side_effects(&self, ctx: &impl MayHaveSideEffectsContext<'a>) -> bool {
93	        self.expressions.iter().any(|e| {
94	            // ToString is called for each expression.
95	            // If the expression is a Symbol or ToPrimitive returns a Symbol, an error is thrown.
96	            // ToPrimitive returns the value as-is for non-Object values, so we can use it instead of ToString here.
