46	/// `ToPrimitive`
47	///
48	/// <https://tc39.es/ecma262/multipage/abstract-operations.html#sec-toprimitive>
49	pub trait ToPrimitive<'a> {
50	    fn to_primitive(&self, ctx: &impl GlobalContext<'a>) -> ToPrimitiveResult;
51	}
